let SEEN = 0;
function see(value: unknown): void { if (typeof value === "object" && value !== null) SEEN++; }
function kept<V>(value: V): V { STORED = value; return value; }
function collect(k: number): void { if (k % 97 === 0) Bun.gc(true); }
